(()=>{const n=Array.from(document.querySelectorAll("[data-gallery-photo]")),e=document.querySelector("#tx-gallery-dialog");if(!e||typeof e.showModal!="function")return;const o=e.querySelector("[data-gallery-preview]"),i=e.querySelector("[data-gallery-caption]");let t=0;function s(e){t=(e+n.length)%n.length,o.src=n[t].href,o.alt=n[t].querySelector("img").alt,i.textContent=`${t+1} / ${n.length}`}n.forEach((t,n)=>t.addEventListener("click",t=>{t.preventDefault(),s(n),e.showModal()})),e.querySelector(".tx-gallery-close").addEventListener("click",()=>e.close()),e.querySelector(".tx-gallery-prev").addEventListener("click",()=>s(t-1)),e.querySelector(".tx-gallery-next").addEventListener("click",()=>s(t+1)),e.addEventListener("click",t=>{t.target===e&&e.close()}),e.addEventListener("keydown",e=>{(e.key==="ArrowLeft"||e.key==="ArrowRight")&&(e.preventDefault(),s(t+(e.key==="ArrowLeft"?-1:1)))})})()